const defaults=()=>({rememberId:false,id:'',rememberPassword:false});
const key=portal=>'packflow.login.'+(portal==='admin'?'admin':'mobile');
function browserStorage(){try{return globalThis.localStorage;}catch{return null;}}
export function readLoginPreferences(portal,storage=browserStorage()){try{const x=JSON.parse(storage?.getItem(key(portal))||'null');if(!x)return defaults();return {rememberId:x.rememberId===true,id:x.rememberId===true&&typeof x.id==='string'?x.id:'',rememberPassword:x.rememberPassword===true};}catch{return defaults();}}
export function writeLoginPreferences(portal,choice,storage=browserStorage()){const value={rememberId:choice.rememberId===true,id:choice.rememberId?String(choice.id||'').trim():'',rememberPassword:choice.rememberPassword===true};try{storage?.setItem(key(portal),JSON.stringify(value));return !!storage;}catch{return false;}}
export function setPasswordVisibility(input,button,visible){input.type=visible?'text':'password';button.setAttribute('aria-pressed',String(visible));button.setAttribute('aria-label',visible?'Hide password':'Show password');button.textContent=visible?'Hide':'Show';}
export async function saveBrowserPassword(id,password,environment=globalThis){if(!environment.isSecureContext||!environment.PasswordCredential||!environment.navigator?.credentials?.store)return {status:'unsupported'};try{const credential=new environment.PasswordCredential({id,password,name:id});await environment.navigator.credentials.store(credential);return {status:'requested'};}catch{return {status:'declined'};}}
export async function readBrowserPassword(expectedId='',environment=globalThis){if(!environment.isSecureContext||!environment.PasswordCredential||!environment.navigator?.credentials?.get)return null;try{const c=await environment.navigator.credentials.get({password:true,mediation:'silent'});if(c?.type!=='password'||!c.password||(expectedId&&c.id.toLowerCase()!==expectedId.toLowerCase()))return null;return c;}catch{return null;}}
export function loginError(error){const code=error?.code||'';if(code==='auth/invalid-credential'||code==='auth/user-not-found'||code==='auth/wrong-password')return 'ID or password is incorrect, or this login has not been created in Firebase Authentication. Ask administration to check the account.';if(code==='auth/too-many-requests')return 'Too many sign-in attempts. Please wait and try again.';if(code==='auth/network-request-failed')return 'Could not connect. Check the internet connection and try again.';return error?.message||'Sign-in failed. Please try again.';}
